42	// openPreview writes the fixture with its files stamped stamp after the end of
43	// the scan, and opens the detail of its finding. Nothing is answered yet.
44	func openPreview(t *testing.T, fx changeFixture, stamp time.Duration) previewScene {
45		t.Helper()
46		dir := t.TempDir()
47		writeTree(t, dir, fx.files, scannedAtFixed.Add(stamp))
48		m, cmd := step(t, changeModel(t, dir, fx.finding, scannedAtFixed), testutil.Key("enter"))
49		if m.state != StateDetails || m.selectedFinding == nil {
50			t.Fatalf("enter did not open the detail of %s", fx.id)
51		}
52		return previewScene{m: m, dir: dir, fx: fx, cmd: cmd}
53	}
