55	// answered runs the preview Cmd and feeds its answer to the model.
56	func (s previewScene) answered(t *testing.T) previewScene {
57		t.Helper()
58		msg, ok := run(t, s.cmd).(ChangePreviewMsg)
59		if !ok {
60			t.Fatalf("the Cmd enter returned did not answer with a ChangePreviewMsg")
61		}
62		s.msg = msg
63		s.m = feed(t, s.m, msg)
