18	// DEVDESK-753, lot 2, step 4 (the section) and the help of step 6. The states a
19	// stored preview can be in are built in details_change_state_test.go; here the
20	// text is read: the lines of the diff, the cap, the cut, the none and the delta.
21	
22	// ── Reading the section ──────────────────────────────────────────────────────
23	
24	// ansiPlain is the detail without its styling.
25	func ansiPlain(m Model) string { return ansi.Strip(m.buildDetailsContent()) }
26	
27	// textLines are the lines of the detail without styling, the padding cell on the
28	// left and the spaces on the right gone. A marker of a hunk keeps its two spaces.
29	func textLines(m Model) []string {
30		lines := plainLines(m)
31		for i, l := range lines {
32			lines[i] = strings.TrimRight(strings.TrimPrefix(l, " "), " ")
33		}
34		return lines
35	}
36	
37	// blockFrom is the labelled line at index at and the lines that continue it, up
38	// to the next blank line or the next label of the detail.
39	func blockFrom(lines []string, at int) []string {
40		out := []string{lines[at]}
41		for _, next := range lines[at+1:] {
42			if strings.TrimSpace(next) == "" || startsBlockLabel(next) {
43				break
44			}
45			out = append(out, next)
46		}
47		return out
48	}
49	
50	// changeBlock is the Change section: its first line, which starts with "Change:",
51	// and what follows it. Nil when the detail has none.
52	func changeBlock(m Model) []string {
53		lines := textLines(m)
54		for i, l := range lines {
55			if strings.HasPrefix(l, "Change:") {
56				return blockFrom(lines, i)
57			}
58		}
59		return nil
60	}
61	
62	// isDiffRow says whether a line of the section is a row of the diff: the marker
63	// of a change, or the two spaces of an indented hunk marker.
64	func isDiffRow(l string) bool {
65		return strings.HasPrefix(l, "+") || strings.HasPrefix(l, "-") || strings.HasPrefix(l, "  ")
66	}
67	
68	// diffRows are the rows of the diff in a block, without the label line, the
69	// "more lines" marker and the git line.
70	func diffRowsOf(block []string) []string {
71		var rows []string
72		for _, l := range block[min(1, len(block)):] {
73			// The git advice may wrap under its label, on lines that start with spaces.
74			if moreLinesMarker.MatchString(l) || strings.HasPrefix(l, "Git:") {
75				break
76			}
77			if isDiffRow(l) {
78				rows = append(rows, l)
79			}
80		}
81		return rows
82	}
83	
84	// moreLinesMarker is the line that says how many rows the section leaves out.
