3	import (
4		"os"
5		"path/filepath"
6		"slices"
7		"testing"
8		"time"
9	)
10	
11	// DEVDESK-753, lot 2, step 6 (H6): the preview is computed off Update, by the Cmd
12	// the detail starts, and it is fast enough that the section needs no loading
13	// state of its own beyond the footer's announcement. The threshold is wide on
14	// purpose, so the test is not flaky on a loaded runner: it catches a computation
15	// that became slow by an order of magnitude (a scan of the whole tree, a git
16	// command per line), not a few milliseconds.
17	
18	// previewBudget is the median time the preview of the largest fixture may take.
19	const previewBudget = 100 * time.Millisecond
20	
21	// largestChangeFixture is the fixture of the catalog whose change has the most
22	// lines (AVD-DS-0002 adds a user, a group and a switch: 11 lines).
23	func largestChangeFixture(t *testing.T) changeFixture {
24		t.Helper()
25		var best changeFixture
26		most := -1
27		for _, fx := range changeFixtures(t) {
28			msg := computeMisconfigFix(fixtureOnDisk(t, fx), fx.finding, scannedAtFixed)
29			if msg.Err != nil {
30				t.Fatalf("%s: %v", fx.id, msg.Err)
31			}
32			if len(msg.Lines) > most {
33				best, most = fx, len(msg.Lines)
34			}
35		}
36		return best
37	}
38	
39	// The Cmd the detail starts, run as the runtime runs it, on the largest change of
40	// the catalog: the median of 15 runs is far under 100 ms. The measure is
41	// recorded in docs/measurements/ by the documentation step.
42	func TestThePreviewOfTheLargestChangeIsFarUnderTheBudget(t *testing.T) {
43		fx := largestChangeFixture(t)
44		const runs = 15
45		elapsed := make([]time.Duration, 0, runs)
46		for range runs {
47			s := openPreview(t, fx, -time.Hour)
48			start := time.Now()
49			msg, ok := run(t, s.cmd).(ChangePreviewMsg)
50			took := time.Since(start)
51			if !ok || msg.Prepared.Err != nil || len(msg.Prepared.Lines) == 0 {
52				t.Fatalf("%s: answer %+v", fx.id, msg)
53			}
54			elapsed = append(elapsed, took)
55		}
56		slices.Sort(elapsed)
57		if median := elapsed[len(elapsed)/2]; median > previewBudget {
58			t.Errorf("the preview of %s takes %v (median of %d, worst %v), the budget is %v: it needs a loading state of its own (H6)",
59				fx.id, median, runs, elapsed[len(elapsed)-1], previewBudget)
60		}
61	}
62	
63	// BenchmarkComputeMisconfigFix measures the shared computation on the largest
64	// fixture of the catalog (AVD-DS-0002), in a directory that is not a git
65	// repository. The case with git is measured by hand for the measurement note: a
66	// benchmark may not start a process of its own.
67	func BenchmarkComputeMisconfigFix(b *testing.B) {
68		fx := dockerfileFixture("AVD-DS-0002", "FROM debian:12\nRUN apt-get install -y curl\nENTRYPOINT [\"/app\"]\n", 1, 3)
69		dir := b.TempDir()
70		path := filepath.Join(dir, "Dockerfile")
71		if err := os.WriteFile(path, []byte(fx.files["Dockerfile"]), 0o644); err != nil {
72			b.Fatal(err)
73		}
74		if err := os.Chtimes(path, scannedAtFixed.Add(-time.Hour), scannedAtFixed.Add(-time.Hour)); err != nil {
75			b.Fatal(err)
76		}
77		b.ReportAllocs()
78		for b.Loop() {
79			if msg := computeMisconfigFix(dir, fx.finding, scannedAtFixed); msg.Err != nil {
80				b.Fatal(msg.Err)
81			}
82		}
83	}
