94	// A diff of at most eight rows is shown whole, under the file, then the git
95	// advice the modal shows.
96	func TestTheSectionShowsTheFileTheDiffAndTheGitAdvice(t *testing.T) {
97		s := openPreview(t, fixtureFor(t, "AVD-DS-0021"), -time.Hour).answered(t)
98		s.m = feed(t, s.m, testutil.Resize(120, 28))
99		block := changeBlock(s.m)
100	
101		if len(block) < 2 || block[0] != "Change: Dockerfile" {
102			t.Fatalf("the section reads %q, want it to start with \"Change: Dockerfile\"", block)
103		}
104		lines := s.msg.Prepared.Lines
105		if len(lines) == 0 || len(lines) > 8 {
106			t.Fatalf("the fixture has %d lines, want 1 to 8", len(lines))
107		}
108		if got := block[1 : 1+len(lines)]; !slices.Equal(got, lines) {
109			t.Errorf("the rows of the section are not the lines of the preview:\n got: %q\nwant: %q", got, lines)
110		}
