116		git := strings.Join(strings.Fields(strings.Join(block[1+len(lines):], " ")), " ")
117		if want := "Git: " + gitAdvice(s.msg.Prepared.File); git != want {
118			t.Errorf("after the rows the section reads %q, want %q", git, want)
119		}
