63	// BenchmarkComputeMisconfigFix measures the shared computation on the largest
64	// fixture of the catalog (AVD-DS-0002), in a directory that is not a git
65	// repository. The case with git is measured by hand for the measurement note: a
66	// benchmark may not start a process of its own.
67	func BenchmarkComputeMisconfigFix(b *testing.B) {
68		fx := dockerfileFixture("AVD-DS-0002", "FROM debian:12\nRUN apt-get install -y curl\nENTRYPOINT [\"/app\"]\n", 1, 3)
69		dir := b.TempDir()
70		path := filepath.Join(dir, "Dockerfile")
71		if err := os.WriteFile(path, []byte(fx.files["Dockerfile"]), 0o644); err != nil {
72			b.Fatal(err)
73		}
74		if err := os.Chtimes(path, scannedAtFixed.Add(-time.Hour), scannedAtFixed.Add(-time.Hour)); err != nil {
75			b.Fatal(err)
76		}
77		b.ReportAllocs()
78		for b.Loop() {
79			if msg := computeMisconfigFix(dir, fx.finding, scannedAtFixed); msg.Err != nil {
80				b.Fatal(msg.Err)
81			}
82		}
83	}
