60		// FindingFile is the file the finding points at, which the verification
61		// looks in. It is File.File for every rule but the build context's, whose
62		// fix edits the .dockerignore beside the Dockerfile it reports (§3.81).
63		FindingFile string
64		// Scope is what the verification looks for: the workload an edit clears for
65		// every container, or the zero value for a fix of one occurrence
66		// (DEVDESK-688).
67		Scope remediation.Scope
68		// Lines is the diff as the preview and the confirmation show it: markers,
69		// sanitized, neither capped nor cut (DEVDESK-753).
70		Lines []string
71		Err   error
72	}
73	
74	// MisconfigFixWrittenMsg reports the write. File is the file written,
75	// FindingFile the one the rule was reported in.
76	type MisconfigFixWrittenMsg struct {
77		Target      string
78		File        string
79		FindingFile string
80		Rule        string
81		Instance    string
82		Scope       remediation.Scope
83		Err         error
84	}
85	
86	// ── Availability ─────────────────────────────────────────────────────────────
87	
88	// canFixMisconfig is the one computation behind the shortcut column and the
89	// handler (Rule 130). It answers in the order the user would ask: am I in the
90	// right place, is there a row, can its file be written at all, and is this rule
91	// one the catalog knows.
92	//
93	// The last question runs the fix itself. That is deliberate: a rule can be in
94	// the catalog and still decline this instance — a base image whose distribution
95	// cannot be identified, a stage that already sets a user — and greying out on
96	// "the catalog has an entry" while the handler then refuses would be exactly
97	// the two computations Rule 130 forbids.
98	func (m Model) canFixMisconfig() shortcut.Availability {
99		if m.activeTab != TabMisconfig {
100			return shortcut.Unavailable(reasonNotMisconfigTab)
101		}
102		f, ok := m.subjectFinding()
103		if !ok {
104			return shortcut.Unavailable(reasonNoFinding)
105		}
106		_, a := misconfigFixAvailability(f, m.targetOnDisk())
107		return a
108	}
109	
110	// misconfigFixAvailability is what canFixMisconfig answers for a finding once a
111	// row exists, and what the finding detail reads for its fix status, so the two
112	// cannot disagree (Rule 130). onDisk says whether the target is a directory:
113	// an image's files are inside it, where nothing can be written. It also returns
114	// the catalog rule, whenever the catalog has one, so a caller can say what the
115	// fix would do even where it cannot run.
116	func misconfigFixAvailability(f scan.Finding, onDisk bool) (remediation.Rule, shortcut.Availability) {
117		rule, ok := remediation.FixFor(f)
118		if !onDisk {
119			return rule, shortcut.Unavailable(reasonFileNotOnDisk)
120		}
121		if !ok {
122			return rule, shortcut.Unavailable(noFixReason(f))
123		}
124		// A refusal the finding alone settles (DEVDESK-688): greyed in advance, with
125		// the reason the press of the key would give.
126		if rule.Declines != nil {
127			if reason := rule.Declines(f); reason != "" {
128				return rule, shortcut.Unavailable(reason)
129			}
130		}
131		// Reading the file here would be I/O on a path the header calls every
132		// frame, so the declines that need the content are left to the Cmd and
133		// reach the footer. What is settled here is everything the finding alone
134		// can answer.
135		return rule, shortcut.Availability{}
136	}
137	
138	// noFixReason is why a finding with no fix in the catalog is refused: for a Pod
139	// Security finding, what the manifest is missing (DEVDESK-689); for anything
140	// else, the generic refusal. The fix is tried first, so a rule that has one never
141	// reaches the missing text.
142	func noFixReason(f scan.Finding) string {
143		if text, ok := remediation.MissingFor(f); ok {
144			return text
145		}
146		return remediation.ReasonNoFixForRule
147	}
148	
149	// ── Preparing ────────────────────────────────────────────────────────────────
150	
151	// prepareMisconfigFix starts the fix by computing it: nothing is asked of the
152	// user until the file has been read, rewritten and put to git, so the
153	// confirmation can state what it is about.
154	func (m Model) prepareMisconfigFix() (tea.Model, tea.Cmd) {
155		if a := m.canFixMisconfig(); !a.Enabled() {
156			return m, m.footer.Warn(a.Reason)
157		}
158		f, _ := m.subjectFinding()
159		var scannedAt time.Time // when the result on screen was measured
160		if m.result != nil {
161			scannedAt = m.result.EndTime
162		}
163		return m, prepareMisconfigFixCmd(m.targetPath, f, scannedAt)
164	}
165	
166	// prepareMisconfigFixCmd runs computeMisconfigFix off Update (Rule 110). The
167	// finding is copied in. scannedAt is when the result on screen was measured.
168	//
169	// A rule that declines here is not an error: it is an answer, and it reaches the
170	// footer as a warning rather than as a failure.
171	func prepareMisconfigFixCmd(target string, f scan.Finding, scannedAt time.Time) tea.Cmd {
172		return func() tea.Msg { return computeMisconfigFix(target, f, scannedAt) }
173	}
174	
175	// errDeclined carries a catalog refusal through the same channel as a failure,
176	// so the handler has one message to read, and tells the two apart by type rather
177	// than by inspecting a string.
178	type errDeclined struct{ reason string }
179	
180	func (e errDeclined) Error() string { return e.reason }
181	
182	// ── Confirming and writing ───────────────────────────────────────────────────
183	
184	func (m Model) handleMisconfigFixPrepared(msg MisconfigFixPreparedMsg) (tea.Model, tea.Cmd) {
185		if msg.Target != m.targetPath {
186			return m, nil // an answer about a result no longer on screen
187		}
188		if d, ok := msg.Err.(errDeclined); ok {
189			// Nothing failed: the catalog will not fix this instance, and says why.
190			return m, m.footer.Warn(d.reason)
191		}
192		if msg.Err != nil {
193			log.Printf("ERROR [security/misconfig] prepare fix: %v", msg.Err)
194			return m, m.footer.Error("Could not prepare the fix — the file may have changed, check logs")
195		}
196		m.misconfigPending = &msg.File
197		m.misconfigFinding = misconfigFindingRef{Rule: msg.Rule, Instance: msg.Instance, File: msg.FindingFile, Scope: msg.Scope}
198		// Rule 104: the safe answer is the default — ConfirmModal opens on No.
199		m.confirmModal = sharedcomponents.NewConfirmModal("Fix misconfiguration", misconfigConfirmationText(msg.File, msg.Body))
200		return m, nil
201	}
202	
203	// misconfigConfirmationText shows the diff itself, not a summary of it.
204	//
205	// A base image bump is one token replaced by another and reads as a sentence; a
206	// misconfiguration fix inserts a block, and no sentence conveys what is about to
207	// land in the file. What the user agrees to is the diff, so the diff is what the
208	// modal shows — followed by what git will and will not be able to undo.
209	func misconfigConfirmationText(f preparedWrite, body string) string {
210		return body + "\n" + fmt.Sprintf("%s: %s\n", f.File, gitAdvice(f))
211	}
212	
213	// handleMisconfigFixConfirmed runs the write the modal was about.
214	func (m Model) handleMisconfigFixConfirmed() (tea.Model, tea.Cmd) {
215		file, ref := m.misconfigPending, m.misconfigFinding
216		m.misconfigPending = nil
217		m.misconfigFinding = misconfigFindingRef{}
218		m.confirmModal = nil
219		if file == nil {
220			return m, nil
221		}
222		return m, writeMisconfigFixCmd(m.targetPath, ref, *file)
223	}
224	
225	func writeMisconfigFixCmd(target string, ref misconfigFindingRef, f preparedWrite) tea.Cmd {
226		return func() tea.Msg {
227			err := patch.WriteIfUnchanged(f.Path, f.Original, f.Updated)
228			return MisconfigFixWrittenMsg{
229				Target: target, File: f.File, FindingFile: ref.File,
230				Rule: ref.Rule, Instance: ref.Instance, Scope: ref.Scope, Err: err,
231			}
232		}
233	}
234	
235	// misconfigFindingRef is the finding a pending fix is about, kept between the
236	// confirmation and the write so the verification knows what to look for.
237	type misconfigFindingRef struct {
238		// Rule is the AVD id.
239		Rule string
240		// Instance is which occurrence of it, so a file holding the same rule
241		// twice is not judged by the one the fix did not touch.
242		Instance string
243		// File is where the finding points, which is not always the file written.
244		File string
245		// Scope is the workload the fix clears, when it clears one.
246		Scope remediation.Scope
247	}
248	
249	func (m Model) handleMisconfigFixWritten(msg MisconfigFixWrittenMsg) (tea.Model, tea.Cmd) {
250		if msg.Target != m.targetPath {
251			return m, nil
252		}
253		if msg.Err != nil {
254			cmd := m.reportFailedFix(msg)
255			return m, cmd
256		}
257		// The file changed; the result did not. A re-scan is what turns "written"
258		// into "fixed", so it starts here rather than being left to the user — as a
259		// job, visible in `:jobs` and stoppable with K.
260		v := misconfigVerify{Target: msg.Target, Rule: msg.Rule, File: msg.FindingFile, Instance: msg.Instance, Scope: msg.Scope}
261		m.misconfigVerifying = &v
262		scan := m.startMisconfigVerification(v)
263		footer := m.footer.Info(fmt.Sprintf("Fixed %s — re-scanning to confirm %s is gone", msg.File, msg.Rule))
264		return m, tea.Batch(scan, footer)
265	}
266	
267	// handleScanFinishedForFix is handleInventoryScanFinished, plus what a fix
268	// waiting on that scan needs. A scan of the target a fix is waiting on answers
269	// that fix, whoever started it: the verification does not need to be the run
270	// that reports. A scan that failed or was stopped never reaches the verdict, so
271	// the pending state ends here, or the detail would say "Re-scanning" for ever.
272	func (m Model) handleScanFinishedForFix(msg InventoryScanFinishedMsg) (tea.Model, tea.Cmd) {
273		v := m.misconfigVerifying
274		if v == nil || v.Target != msg.Name {
275			return m.handleInventoryScanFinished(msg)
276		}
277		if msg.Err != nil {
278			m.misconfigVerifying = nil
279			return m.handleInventoryScanFinished(msg)
280		}
281		next, cmd := m.handleInventoryScanFinished(msg)
282		return next, tea.Batch(cmd, verifyMisconfigCmd(*v))
283	}
284	
285	// reportFailedFix sets the footer on the model it is called on, which is why it
286	// takes a pointer: on a copy the message would be set and then thrown away.
287	func (m *Model) reportFailedFix(msg MisconfigFixWrittenMsg) tea.Cmd {
288		if errors.Is(msg.Err, patch.ErrChanged) {
289			return m.footer.Error(fmt.Sprintf("%s changed since the preview — review it again", msg.File))
290		}
291		log.Printf("ERROR [security/misconfig] write %s: %v", msg.File, msg.Err)
292		return m.footer.Error(fmt.Sprintf("Failed to write %s — check logs", msg.File))
293	}
294	
295	// ── Verifying (§3.78, phase B3) ──────────────────────────────────────────────
296	//
297	// A written file is not a fixed one. The rule that was faulted is still in the
298	// result on screen, because that result was measured before the edit — and the
299	// whole discipline §3.2 set for base images is that a fix is judged by a
300	// re-scan, never by the confidence of whatever produced it. So the write starts
301	// one, and the verdict it reports is binary: the rule is gone, or it is not.
302	//
303	// The scan is an ordinary job (§3.58), which is what makes starting it on the
304	// user's behalf acceptable: it shows up in `:jobs` with a label saying why, and
305	// `K` stops it. Nothing is hidden and nothing is unstoppable.
306	
307	// misconfigVerify is the fix waiting on a re-scan to say whether it worked.
308	type misconfigVerify struct {
309		Target string
310		Rule   string
311		// File is the file the finding points at, where the rule is looked for.
312		File     string
313		Instance string
314		// Scope is what a rule that clears a whole workload is looked for in
315		// (DEVDESK-688). The zero value: this occurrence, through holdsRule.
316		Scope remediation.Scope
317	}
318	
319	// MisconfigVerifiedMsg is the verdict: whether the rule the fix was about is
320	// still reported for that file.
321	type MisconfigVerifiedMsg struct {
322		Target  string
323		Rule    string
324		File    string
325		Cleared bool
326		// Scope is the scope the verdict was judged by; the zero value for a fix of
327		// one occurrence.
328		Scope remediation.Scope
329		// Still lists the rule ids the re-scan still reports in the scope of the
330		// fix; Cleared is true when it is empty (DEVDESK-688).
331		Still []string
332		// Result is the scan the verdict was read from, so the tab can stop showing
333		// findings the edit has already dealt with.
334		Result *scan.Result
335		Err    error
336	}
337	
338	// startMisconfigVerification re-scans the target the fix was written into.
339	//
340	// It runs even when the catalog is sure of itself, because being sure is not
341	// the same as having measured — and the cases where a rule survives its own fix
342	// are exactly the ones nobody predicted.
343	func (m Model) startMisconfigVerification(v misconfigVerify) tea.Cmd {
344		if m.scanningTarget(v.Target) {
345			// Something is already measuring this target; its result will answer.
346			return nil
347		}
348		job := inventoryScanJob{Kind: kindRepo, Name: v.Target}
349		opts := m.scanOptions()
350		return jobs.StartInContext(
351			jobs.NewRun(jobs.KindScan, command.ViewSecurity, "", "verify fix", v.Target),
352			func(contextName string) tea.Cmd {
353				return rescanCmd([]inventoryScanJob{job}, opts, contextName)
354			},
355		)
356	}
357	
358	// verifyMisconfigCmd reads the result the re-scan stored and answers whether the
359	// rule is still there. It runs off Update (Rule 110).
360	func verifyMisconfigCmd(v misconfigVerify) tea.Cmd {
361		return func() tea.Msg {
362			result, err := cache.ReadWorkspaceScanResult(v.Target)
363			if err != nil {
364				return MisconfigVerifiedMsg{Target: v.Target, Rule: v.Rule, File: v.File, Err: err}
365			}
366			still := stillReported(result, v)
367			return MisconfigVerifiedMsg{
368				Target: v.Target, Rule: v.Rule, File: v.File,
369				Cleared: len(still) == 0, Still: still, Scope: v.Scope, Result: result,
370			}
371		}
372	}
373	
374	// stillReported lists the rule ids the result still reports for the fix v.
375	//
376	// Without a scope it is holdsRule on the occurrence that was fixed. With one, it
377	// is each rule of the scope looked for in the lines of the edited workload: one
378	// edit cleared them for every container of the pod, so a finding on another
379	// container still counts, and a finding of another workload of the file does not.
380	// A scope with no lines (0, 0: the computation failed) reads the whole file, the
381	// safe side: "still reported" at worst, never a "fixed" that was not measured.
382	func stillReported(result *scan.Result, v misconfigVerify) []string {
383		if len(v.Scope.Rules) == 0 {
384			if holdsRule(result, v.Rule, v.File, v.Instance) {
385				return []string{v.Rule}
386			}
387			return nil
388		}
389		if result == nil {
390			return nil
391		}
392		var still []string
393		for _, rule := range v.Scope.Rules {
394			if holdsRuleInScope(result, rule, v.File, v.Scope) {
395				still = append(still, rule)
396			}
397		}
398		return still
399	}
400	
401	// holdsRuleInScope says whether the result reports rule in file, at a line that
402	// is inside the scope's lines (anywhere in the file when the scope has none). A
403	// finding with no line (Line <= 0) cannot be placed outside the scope, so it
404	// counts as inside: the safe side.
405	func holdsRuleInScope(result *scan.Result, rule, file string, scope remediation.Scope) bool {
406		want := remediation.RuleKey(rule)
407		wholeFile := scope.Line == 0 && scope.EndLine == 0
408		for _, f := range result.Findings {
409			if scan.Categorize(f) != scan.CategoryMisconfiguration || f.File != file || remediation.RuleKey(f.ID) != want {
410				continue
411			}
412			if wholeFile || f.Line <= 0 || (f.Line >= scope.Line && f.Line <= scope.EndLine) {
413				return true
414			}
415		}
416		return false
417	}
418	
419	// holdsRule says whether a result still reports this rule for this file —
420	// and, when instance is set, this occurrence of it.
421	//
422	// It matches through remediation.RuleKey rather than on the string, for the
423	// reason the catalog does: Trivy spells one rule two ways, and a comparison
424	// that missed the other spelling would report every fix as successful.
425	//
426	// The occurrence matters for a manifest (§3.80): a Deployment with two
427	// containers is flagged for KSV-0001 twice in one file, and the fix edits one
428	// of them. Judged on the rule and the file alone, the untouched container
429	// would read as the fix having failed.
430	func holdsRule(result *scan.Result, rule, file, instance string) bool {
431		if result == nil {
432			return false
433		}
434		want := remediation.RuleKey(rule)
435		for _, f := range result.Findings {
436			if scan.Categorize(f) != scan.CategoryMisconfiguration {
437				continue
438			}
439			if f.File == file && remediation.RuleKey(f.ID) == want && (instance == "" || instanceOf(f) == instance) {
440				return true
441			}
442		}
443		return false
444	}
445	
446	// instanceOf identifies one occurrence of a rule in a file, without its line,
447	// which the fix itself moves. Trivy words the occurrence in Message ("Container
448	// 'api' of Deployment 'web' should set…"), kubeconform in Title
449	// ("Deployment/web: …"); the pair covers both.
450	func instanceOf(f scan.Finding) string {
451		return f.Title + "\n" + f.Message
452	}
453	
454	// handleMisconfigVerified reports the verdict, and swaps in the result it was
455	// read from.
456	//
457	// The swap is what keeps the screen from contradicting the footer: without it a
458	// line saying the rule is gone would sit above a table still listing it.
459	func (m Model) handleMisconfigVerified(msg MisconfigVerifiedMsg) (tea.Model, tea.Cmd) {
460		if msg.Target != m.targetPath {
461			return m, nil
462		}
463		m.misconfigVerifying = nil
464		if msg.Err != nil {
465			log.Printf("ERROR [security/misconfig] verify %s: %v", msg.Rule, msg.Err)
466			return m, m.footer.Error("Could not read the verification scan — check logs")
467		}
468		if msg.Result != nil {
469			m.setResult(msg.Result)
470		}
471		if !msg.Cleared {
472			// Not a failure: the file was written, and the rule still fires. Saying
473			// so is the only honest answer, and it is why the scan exists.
474			ids := msg.Still
475			if len(ids) == 0 {
476				ids = []string{msg.Rule}
477			}
478			return m, m.footer.Warn(fmt.Sprintf("%s still reported in %s after the fix", strings.Join(ids, " and "), msg.File))
479		}
480		if len(msg.Scope.Rules) > 0 {
481			return m, m.footer.Info(fmt.Sprintf("%s cleared for the whole pod in %s — confirmed by a re-scan",
482				strings.Join(msg.Scope.Rules, " and "), msg.File))
483		}
484		return m, m.footer.Info(fmt.Sprintf("%s cleared in %s — confirmed by a re-scan", msg.Rule, msg.File))
485	}
