package security

import (
	"fmt"
	"github.com/anthnel/devdesk/internal/shared"
	"log"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/jobs"

	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// Update handles messages
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	// Handle confirm modal messages first (before passing to modal)
	switch msg := msg.(type) {
	case sharedcomponents.ConfirmModalYesMsg:
		// The write of the chosen base images takes the answer when it is the
		// question that was asked.
		if m.remediation.pending != nil {
			return m.handleRemediationConfirmed()
		}
		// So does the misconfiguration fix, which is the same act on another
		// tab and therefore another question.
		if m.misconfigPending != nil {
			return m.handleMisconfigFixConfirmed()
		}
		// User confirmed to ignore the secret
		if m.findingToIgnore != nil {
			finding := *m.findingToIgnore
			targetDir := m.targetPath
			m.confirmModal = nil
			m.findingToIgnore = nil
			return m, func() tea.Msg {
				err := scan.AddToGitleaksIgnore(targetDir, finding)
				return SecretIgnoredMsg{Finding: finding, Error: err}
			}
		}
		m.confirmModal = nil
		m.findingToIgnore = nil
		return m, nil

	case sharedcomponents.ConfirmModalNoMsg:
		// User cancelled: nothing is written, and nothing is remembered of it.
		m.confirmModal = nil
		m.findingToIgnore = nil
		m.remediation.pending = nil
		m.misconfigPending = nil
		m.misconfigFinding = misconfigFindingRef{}
		return m, nil

	case sharedcomponents.OptionConfirmModalYesMsg:
		m.scanAllModal = nil
		return m.rescanAll(msg.Option)

	case sharedcomponents.OptionConfirmModalNoMsg:
		m.scanAllModal = nil
		return m, nil

	// The router's detection (§3.86): a rescan runs on it rather than probing
	// the machine again.
	case shared.ScanToolsMsg:
		m.deps = msg.Report
		return m, nil

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		// Widths and height in one call; SetHeight accounts for the header row
		// internally, so m.height goes through as it is. Rows no longer depend
		// on the width — bubbles truncates each cell to its own column — so
		// there is nothing to rebuild here.
		m.resizeFindings()
		m.inventory.Resize(m.width, max(m.height, 5))
		// Update details viewport size and refresh content
		m.sizeDetails()
		if m.state == StateDetails {
			m.detailsViewport.SetContent(m.buildDetailsContent())
		}
		return m, nil

	case tea.KeyPressMsg:
		// Whichever modal is open takes every key before the view sees one.
		if m.confirmModal != nil {
			var cmd tea.Cmd
			m.confirmModal, cmd = m.confirmModal.Update(msg)
			return m, cmd
		}
		if m.scanAllModal != nil {
			var cmd tea.Cmd
			m.scanAllModal, cmd = m.scanAllModal.Update(msg)
			return m, cmd
		}
		return m.handleKeyMsg(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)

	case SecretIgnoredMsg:
		if msg.Error != nil {
			log.Printf("ERROR [security] ignore secret %s: %v", msg.Finding.File, msg.Error)
			return m, m.footer.Error("Failed to ignore secret — check logs")
		}
		return m, m.footer.Info(fmt.Sprintf("Added %s to .gitleaksignore", msg.Finding.File))

	case InventoryLoadedMsg:
		return m.handleInventoryLoaded(msg)

	case InventoryResultLoadedMsg:
		return m.handleInventoryResultLoaded(msg)

	case InventoryScanFinishedMsg:
		return m.handleScanFinishedForFix(msg)

	case InventoryScanStartingMsg:
		// The row is already spinning: the router recorded the transition
		// before handing the message on, and the snapshot rebuilt the rows.
		return m, nil

	case RemediationDiscoveredMsg:
		return m.handleRemediationDiscovered(msg)

	case BaseImageUpdatesCheckedMsg:
		return m.handleBaseImageUpdatesChecked(msg)

	case RemediationScanFinishedMsg:
		return m.handleRemediationScanFinished(msg)

	case RemediationSignaturesMsg:
		return m.handleRemediationSignatures(msg)

	case RemediationWritePreparedMsg:
		return m.handleRemediationWritePrepared(msg)

	case RemediationWrittenMsg:
		return m.handleRemediationWritten(msg)

	case MisconfigFixPreparedMsg:
		return m.handleMisconfigFixPrepared(msg)

	case MisconfigFixWrittenMsg:
		return m.handleMisconfigFixWritten(msg)

	case MisconfigVerifiedMsg:
		return m.handleMisconfigVerified(msg)

	case FixCommandCopiedMsg:
		return m.handleFixCommandCopied(msg)

	case FindingFileRefusedMsg:
		return m, m.footer.Warn(msg.Reason)

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case jobs.FrameMsg:
		return m.handleFrameMsg(msg)
	}

	m.footer.Handle(msg)
	return m, nil
}

// handlePaste hands pasted text to the filter bar of the table on screen while
// it has the keyboard and no modal is open; otherwise a paste is dropped, never
// read as keys (Rule 111).
func (m Model) handlePaste(msg tea.PasteMsg) (tea.Model, tea.Cmd) {
	if m.confirmModal != nil || m.scanAllModal != nil {
		return m, nil
	}
	switch {
	case m.state == StateInventory && m.inventory.InEditMode():
		return m, m.inventory.Update(msg)
	case m.state == StateResults && m.findingsTable.InEditMode():
		return m, m.findingsTable.Update(msg)
	}
	return m, nil
}

// handleKeyMsg processes keyboard input
func (m Model) handleKeyMsg(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch m.state {
	case StateInventory:
		return m.handleInventoryState(msg)
	case StateResults:
		return m.handleResultsState(msg)
	case StateDetails:
		return m.handleDetailsState(msg)
	}
	return m, nil
}

