235	// misconfigFindingRef is the finding a pending fix is about, kept between the
236	// confirmation and the write so the verification knows what to look for.
237	type misconfigFindingRef struct {
238		// Rule is the AVD id.
239		Rule string
240		// Instance is which occurrence of it, so a file holding the same rule
241		// twice is not judged by the one the fix did not touch.
242		Instance string
243		// File is where the finding points, which is not always the file written.
244		File string
245		// Scope is the workload the fix clears, when it clears one.
246		Scope remediation.Scope
247	}
