	"slices"
	"testing"
	"time"
)

func TestZZMeasure(t *testing.T) {
	fx := dockerfileFixture("AVD-DS-0002", "FROM debian:12\nRUN apt-get install -y curl\nENTRYPOINT [\"/app\"]\n", 1, 3)
	for _, withGit := range []bool{false, true} {
		dir := t.TempDir()
		path := filepath.Join(dir, "Dockerfile")
		os.WriteFile(path, []byte(fx.files["Dockerfile"]), 0o644)
		os.Chtimes(path, scannedAtFixed.Add(-time.Hour), scannedAtFixed.Add(-time.Hour))
		if withGit {
			for _, args := range [][]string{{"init", "-q"}, {"add", "."}, {"-c", "user.name=x", "-c", "user.email=x@x", "commit", "-q", "-m", "x"}} {
				c := exec.Command("git", args...)
				c.Dir = dir
				if out, err := c.CombinedOutput(); err != nil {
					t.Fatalf("%v %s", err, out)
				}
			}
			os.Chtimes(path, scannedAtFixed.Add(-time.Hour), scannedAtFixed.Add(-time.Hour))
		}
		var el []time.Duration
		for range 101 {
			s := time.Now()
			msg := computeMisconfigFix(dir, fx.finding, scannedAtFixed)
			el = append(el, time.Since(s))
			if msg.Err != nil {
				t.Fatal(msg.Err)
			}
			_ = msg
		}
		slices.Sort(el)
		t.Logf("git=%v lines=%d median=%v p95=%v max=%v state=%v", withGit, len(computeMisconfigFix(dir, fx.finding, scannedAtFixed).Lines), el[50], el[95], el[100], computeMisconfigFix(dir, fx.finding, scannedAtFixed).File.State)
	}
}
EOF
